import sys
from typing import List, Tuple

def cross_product(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_left_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, a, b) > 0

def is_right_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, b, a) > 0

def is_non_self_intersecting(permutation: List[int], points: List[Tuple[int, int]]) -> bool:
    n = len(permutation)
    for i in range(n):
        for j in range(i + 2, n - 1):
            if (permutation[i] != permutation[j] and permutation[i] != permutation[j + 1] and
                permutation[i + 1] != permutation[j] and permutation[i + 1] != permutation[j + 1]):
                if (cross_product(points[permutation[i] - 1], points[permutation[i + 1] - 1], points[permutation[j] - 1]) *
                    cross_product(points[permutation[i] - 1], points[permutation[i + 1] - 1], points[permutation[j + 1] - 1]) > 0 and
                    cross_product(points[permutation[j] - 1], points[permutation[j + 1] - 1], points[permutation[i] - 1]) *
                    cross_product(points[permutation[j] - 1], points[permutation[j + 1] - 1], points[permutation[i + 1] - 1]) > 0):
                    return False
    return True

def is_winding(permutation: List[int], points: List[Tuple[int, int]], s: str) -> bool:
    n = len(permutation)
    for i in range(n - 2):
        if s[i] == 'L':
            if not is_left_turn(points[permutation[i] - 1], points[permutation[i + 1] - 1], points[permutation[i + 2] - 1]):
                return False
        else:
            if not is_right_turn(points[permutation[i] - 1], points[permutation[i + 1] - 1], points[permutation[i + 1] - 1]):
                return False
    return True

def find_permutation(n: int, points: List[Tuple[int, int]], s: str) -> List[int]:
    for perm in permutations(range(1, n + 1)):
        if is_non_self_intersecting(perm, points) and is_winding(perm, points, s):
            return perm
    return [-1]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(n)]
    s = data[-1]

    result = find_permutation(n, points, s)
    if result == [-1]:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
